import re

def score(text):
    if text == "" or None:
        raise EOFError

    # Extract the JSON part using regex
    json_match = re.search(r'\{.*\}', text, re.DOTALL)
    if not json_match:
        raise RuntimeError("Extracted text is an empty string")
    txt = json_match.group(0)
    # Parse the JSON string to a dictionary

    data = json.loads(txt)

    # Return the score
    return data.get("score", 0)

